from pydantic import BaseModel, Field

app = FastAPI()

class QueryModel(BaseModel):
    q: str = Field(alias="query_param")

@app.get("/query")
async def read_query(params: QueryModel = Query()):
    return params

class HeaderModel(BaseModel):
    h: str = Field(alias="header_param")

@app.get("/header")
async def read_header(params: HeaderModel = Header()):
    return params

class CookieModel(BaseModel):
    c: str = Field(alias="cookie_param")

@app.get("/cookie")
async def read_cookie(params: CookieModel = Cookie()):
    return params

client = TestClient(app)

def test_query_alias():
    response = client.get("/query", params={"query_param": "foo"})
    assert response.status_code == 200
    assert response.json() == {"q": "foo"}

def test_header_alias():
    response = client.get("/header", headers={"header_param": "foo"})
    assert response.status_code == 200
    assert response.json() == {"h": "foo"}

def test_cookie_alias():
    response = client.get("/cookie", cookies={"cookie_param": "foo"})
    assert response.status_code == 200
    assert response.json() == {"c": "foo"}

def test_query_name_should_fail():
    # If we provide the name instead of the alias, it should be an extra parameter
    # and the required alias should be missing.
    response = client.get("/query", params={"q": "foo"})
