def test_header_alias():
    response = client.get("/header", headers={"header_param": "foo"})
    assert response.status_code == 200
    assert response.json() == {"h": "foo"}

def test_cookie_alias():
    response = client.get("/cookie", cookies={"cookie_param": "foo"})
    assert response.status_code == 200
    assert response.json() == {"c": "foo"}

def test_query_name_should_fail():
